//! 表达式求值

use crate::{
    error::EvaluationError,
    parse::{BinOp, Expr, LogicOp, UnOp},
    value::{Number, Value},
};

/// 求值上下文
///
/// 变量与函数全部由调用者提供, 库本身不内置任何变量或函数.
pub trait EvaluationContext {
    /// 变量查找, 未定义时返回 `None`, 对应 [`EvaluationError::UnknownVariable`]
    fn get_variable(&self, name: &str) -> Option<Value>;

    /// 函数调用
    ///
    /// 由调用者决定函数是否存在, 参数个数与返回值.
    /// 未知函数可返回 [`EvaluationError::UnknownFunction`], 参数个数不符可返回
    /// [`EvaluationError::ArgumentCount`], 其他错误可用 [`EvaluationError::Host`] 透传.
    fn call_function(&self, name: &str, arguments: &[Value]) -> Result<Value, EvaluationError>;
}

/// 空上下文, 不提供任何变量或函数
///
/// 用于无上下文求值, 表达式只能使用字面量与运算符.
pub struct EmptyContext;

impl EvaluationContext for EmptyContext {
    fn get_variable(&self, _name: &str) -> Option<Value> {
        None
    }

    fn call_function(&self, name: &str, _arguments: &[Value]) -> Result<Value, EvaluationError> {
        Err(EvaluationError::UnknownFunction(name.to_string()))
    }
}

/// 求值最大嵌套深度
const MAX_DEPTH: usize = 128;

/// 对语法树求值
pub(crate) fn evaluate_ast(
    expression: &Expr,
    context: &dyn EvaluationContext,
    depth: usize,
) -> Result<Value, EvaluationError> {
    if depth >= MAX_DEPTH {
        return Err(EvaluationError::RecursionLimit);
    }
    match expression {
        Expr::Number(number) => Ok(Value::Number(*number)),
        Expr::Bool(boolean) => Ok(Value::Bool(*boolean)),
        Expr::Str(string) => Ok(Value::String(string.clone())),
        Expr::Var(name) => context
            .get_variable(name)
            .ok_or_else(|| EvaluationError::UnknownVariable(name.clone())),
        Expr::Unary(operator, inner) => {
            let value = evaluate_ast(inner, context, depth + 1)?;
            match operator {
                UnOp::Not => Ok(Value::Bool(!value.is_truthy())),
                UnOp::Neg => number_negate(value),
                UnOp::Pos => match value {
                    Value::Number(_) => Ok(value),
                    value => Err(EvaluationError::OperandType { op: "+", value }),
                },
            }
        }
        Expr::Binary(operator, lhs, rhs) => {
            let lhs = evaluate_ast(lhs, context, depth + 1)?;
            let rhs = evaluate_ast(rhs, context, depth + 1)?;
            match operator {
                // `+`: 数值相加; 任一操作数为字符串时拼接 (不允许布尔参与)
                BinOp::Add => {
                    if matches!(&lhs, Value::String(_)) || matches!(&rhs, Value::String(_)) {
                        string_concat(lhs, rhs)
                    } else {
                        number_binary("+", lhs, rhs, |a, b| a + b, |a, b| a.checked_add(b))
                    }
                }
                BinOp::Sub => number_binary("-", lhs, rhs, |a, b| a - b, |a, b| a.checked_sub(b)),
                BinOp::Mul => number_binary("*", lhs, rhs, |a, b| a * b, |a, b| a.checked_mul(b)),
                BinOp::Div => {
                    if is_zero(&rhs) {
                        return Err(EvaluationError::DivisionByZero);
                    }
                    number_binary(
                        "/",
                        lhs,
                        rhs,
                        |a, b| a / b,
                        |a, b| {
                            match a.checked_rem(b) {
                                Some(0) => a.checked_div(b),
                                // 除不尽或溢出时回退浮点数
                                _ => None,
                            }
                        },
                    )
                }
                BinOp::Rem => {
                    if is_zero(&rhs) {
                        return Err(EvaluationError::DivisionByZero);
                    }
                    number_binary("%", lhs, rhs, |a, b| a % b, |a, b| a.checked_rem(b))
                }
                BinOp::Eq => equality("==", lhs, rhs),
                BinOp::Ne => equality("!=", lhs, rhs),
                BinOp::Lt => ordering("<", lhs, rhs),
                BinOp::Gt => ordering(">", lhs, rhs),
                BinOp::LtEq => ordering("<=", lhs, rhs),
                BinOp::GtEq => ordering(">=", lhs, rhs),
            }
        }
        Expr::Logical(operator, lhs, rhs) => {
            let lhs = evaluate_ast(lhs, context, depth + 1)?;
            match operator {
                LogicOp::And => {
                    if !lhs.is_truthy() {
                        Ok(Value::Bool(false))
                    } else {
                        let rhs = evaluate_ast(rhs, context, depth + 1)?;
                        Ok(Value::Bool(rhs.is_truthy()))
                    }
                }
                LogicOp::Or => {
                    if lhs.is_truthy() {
                        Ok(Value::Bool(true))
                    } else {
                        let rhs = evaluate_ast(rhs, context, depth + 1)?;
                        Ok(Value::Bool(rhs.is_truthy()))
                    }
                }
            }
        }
        Expr::Ternary(condition, then_branch, else_branch) => {
            let condition = evaluate_ast(condition, context, depth + 1)?;
            if condition.is_truthy() {
                evaluate_ast(then_branch, context, depth + 1)
            } else {
                evaluate_ast(else_branch, context, depth + 1)
            }
        }
        Expr::Call(name, arguments) => {
            let mut values = Vec::with_capacity(arguments.len());
            for argument in arguments {
                values.push(evaluate_ast(argument, context, depth + 1)?);
            }
            context.call_function(name, &values)
        }
    }
}

/// 字符串拼接, 允许数值与字符串参与, 布尔报错
fn string_concat(lhs: Value, rhs: Value) -> Result<Value, EvaluationError> {
    if matches!(&lhs, Value::Bool(_)) || matches!(&rhs, Value::Bool(_)) {
        return Err(EvaluationError::TypeMismatch { op: "+", lhs, rhs });
    }
    Ok(Value::String(format!("{lhs}{rhs}")))
}

/// 除数是否为零
fn is_zero(value: &Value) -> bool {
    matches!(value, Value::Number(number) if number.as_f64() == 0.0)
}

/// 数值二元运算, 两侧均为整数时尽量保持整数结果
fn number_binary(
    op: &'static str,
    lhs: Value,
    rhs: Value,
    float_operation: impl Fn(f64, f64) -> f64,
    integer_operation: impl Fn(i64, i64) -> Option<i64>,
) -> Result<Value, EvaluationError> {
    if let (Value::Number(lhs), Value::Number(rhs)) = (&lhs, &rhs)
        && let (Some(lhs), Some(rhs)) = (lhs.as_i64(), rhs.as_i64())
        && let Some(result) = integer_operation(lhs, rhs)
    {
        return Ok(Value::Number(Number::Integer(result)));
    }
    match (lhs, rhs) {
        (Value::Number(lhs), Value::Number(rhs)) => {
            match Number::from_f64(float_operation(lhs.as_f64(), rhs.as_f64())) {
                Some(number) => Ok(Value::Number(number)),
                None => Err(EvaluationError::NumberOutOfRange(op)),
            }
        }
        (lhs, rhs) => Err(EvaluationError::TypeMismatch { op, lhs, rhs }),
    }
}

/// 一元负号, 整数取负保持整数
fn number_negate(value: Value) -> Result<Value, EvaluationError> {
    match value {
        Value::Number(number) => match number.as_i64() {
            Some(integer) => match integer.checked_neg() {
                Some(negated) => Ok(Value::Number(Number::Integer(negated))),
                // 溢出 (i64::MIN) 时回退浮点数
                None => number_float_operation("-", number, |value| -value),
            },
            None => number_float_operation("-", number, |value| -value),
        },
        value => Err(EvaluationError::OperandType { op: "-", value }),
    }
}

/// 浮点一元运算
fn number_float_operation(
    op: &'static str,
    number: Number,
    operation: impl Fn(f64) -> f64,
) -> Result<Value, EvaluationError> {
    match Number::from_f64(operation(number.as_f64())) {
        Some(number) => Ok(Value::Number(number)),
        None => Err(EvaluationError::NumberOutOfRange(op)),
    }
}

/// `==` / `!=`: 要求两侧同类型, 数值按数值比较, 返回布尔
fn equality(op: &'static str, lhs: Value, rhs: Value) -> Result<Value, EvaluationError> {
    let equal = match (&lhs, &rhs) {
        (Value::Number(a), Value::Number(b)) => a.as_f64() == b.as_f64(),
        (Value::Bool(a), Value::Bool(b)) => a == b,
        (Value::String(a), Value::String(b)) => a == b,
        _ => return Err(EvaluationError::TypeMismatch { op, lhs, rhs }),
    };
    Ok(Value::Bool(if op == "!=" { !equal } else { equal }))
}

/// `<` `>` `<=` `>=`: 仅数值与字符串, 返回布尔
fn ordering(op: &'static str, lhs: Value, rhs: Value) -> Result<Value, EvaluationError> {
    let ordered = match (&lhs, &rhs) {
        (Value::Number(a), Value::Number(b)) => {
            let (a, b) = (a.as_f64(), b.as_f64());
            compare(op, a, b)
        }
        (Value::String(a), Value::String(b)) => compare(op, a, b),
        _ => return Err(EvaluationError::TypeMismatch { op, lhs, rhs }),
    };
    Ok(Value::Bool(ordered))
}

fn compare<T: PartialOrd>(op: &'static str, lhs: T, rhs: T) -> bool {
    match op {
        "<" => lhs < rhs,
        "<=" => lhs <= rhs,
        ">" => lhs > rhs,
        _ => lhs >= rhs,
    }
}

#[cfg(test)]
mod tests {
    use std::str::FromStr;

    use crate::{Expression, Value};

    use super::*;

    /// 测试用上下文: 提供变量 a=5, b="x", c=true, d=2.5, zero=0, empty="" 与函数 random
    struct Context;

    impl EvaluationContext for Context {
        fn get_variable(&self, name: &str) -> Option<Value> {
            match name {
                "a" => Some(Value::from(5)),
                "b" => Some(Value::from("x")),
                "c" => Some(Value::from(true)),
                "d" => Some(Value::Number(Number::Float(2.5))),
                "zero" => Some(Value::from(0)),
                "empty" => Some(Value::from("")),
                _ => None,
            }
        }

        fn call_function(&self, name: &str, arguments: &[Value]) -> Result<Value, EvaluationError> {
            match name {
                "random" => {
                    if arguments.len() != 3 {
                        return Err(EvaluationError::ArgumentCount {
                            name: name.into(),
                            expected: 3,
                            got: arguments.len(),
                        });
                    }
                    Ok(Value::from(7))
                }
                "now" => {
                    if !arguments.is_empty() {
                        return Err(EvaluationError::ArgumentCount {
                            name: name.into(),
                            expected: 0,
                            got: arguments.len(),
                        });
                    }
                    Ok(Value::from(42))
                }
                _ => Err(EvaluationError::UnknownFunction(name.into())),
            }
        }
    }

    fn evaluate(source: &str) -> Result<Value, EvaluationError> {
        Expression::from_str(source)
            .unwrap_or_else(|error| panic!("应成功解析 `{source}`: {error}"))
            .evaluate(&Context)
    }

    // -------- 算术 --------

    #[test]
    fn arithmetic() {
        assert_eq!(evaluate("a + 1").unwrap(), Value::from(6));
        assert_eq!(evaluate("a - 1").unwrap(), Value::from(4));
        assert_eq!(evaluate("a * 2").unwrap(), Value::from(10));
        assert_eq!(
            evaluate("a / 2").unwrap(),
            Value::Number(Number::Float(2.5))
        );
        assert_eq!(evaluate("a % 2").unwrap(), Value::from(1));
        assert_eq!(evaluate("2 + 3 * 4").unwrap(), Value::from(14));
        assert_eq!(evaluate("(2 + 3) * 4").unwrap(), Value::from(20));
        assert_eq!(evaluate("5 - -3").unwrap(), Value::from(8));
        assert_eq!(evaluate("-a").unwrap(), Value::from(-5));
        assert_eq!(evaluate("+a").unwrap(), Value::from(5));
    }

    #[test]
    fn integer_arithmetic_stays_integer() {
        // 整数结果保持整数表示
        assert_eq!(
            evaluate("1 + 2").unwrap(),
            Value::Number(Number::Integer(3))
        );
        assert_eq!(
            evaluate("10 / 2").unwrap(),
            Value::Number(Number::Integer(5))
        );
        assert_eq!(
            evaluate("10 % 3").unwrap(),
            Value::Number(Number::Integer(1))
        );
        // 除不尽时回退浮点数
        assert_eq!(
            evaluate("10 / 4").unwrap(),
            Value::Number(Number::Float(2.5))
        );
        // 整数溢出时回退浮点数
        assert!(matches!(
            evaluate("9223372036854775807 + 1").unwrap(),
            Value::Number(Number::Float(_))
        ));
    }

    #[test]
    fn division_by_zero() {
        assert_eq!(
            evaluate("1 / 0").unwrap_err(),
            EvaluationError::DivisionByZero
        );
        assert_eq!(
            evaluate("a / zero").unwrap_err(),
            EvaluationError::DivisionByZero
        );
        assert_eq!(
            evaluate("1 % 0").unwrap_err(),
            EvaluationError::DivisionByZero
        );
    }

    // -------- 字符串 --------

    #[test]
    fn string_concat() {
        assert_eq!(evaluate("a + b").unwrap(), Value::from("5x"));
        assert_eq!(evaluate("b + a").unwrap(), Value::from("x5"));
        assert_eq!(evaluate("b + b").unwrap(), Value::from("xx"));
        assert_eq!(evaluate("\"n\" + a").unwrap(), Value::from("n5"));
        assert_eq!(evaluate("a + \"!\"").unwrap(), Value::from("5!"));
        assert_eq!(evaluate("a + b + \"!\"").unwrap(), Value::from("5x!"));
        assert_eq!(evaluate("2.5 + \"x\"").unwrap(), Value::from("2.5x"));
    }

    #[test]
    fn type_mismatches() {
        assert!(matches!(
            evaluate("a + c").unwrap_err(),
            EvaluationError::TypeMismatch { op: "+", .. }
        ));
        assert!(matches!(
            evaluate("b - a").unwrap_err(),
            EvaluationError::TypeMismatch { op: "-", .. }
        ));
        assert!(matches!(
            evaluate("\"x\" * 2").unwrap_err(),
            EvaluationError::TypeMismatch { op: "*", .. }
        ));
        assert!(matches!(
            evaluate("a == \"5\"").unwrap_err(),
            EvaluationError::TypeMismatch { op: "==", .. }
        ));
        assert!(matches!(
            evaluate("c < true").unwrap_err(),
            EvaluationError::TypeMismatch { op: "<", .. }
        ));
        assert!(matches!(
            evaluate("-\"x\"").unwrap_err(),
            EvaluationError::OperandType { op: "-", .. }
        ));
    }

    // -------- 比较 --------

    #[test]
    fn comparisons() {
        assert_eq!(evaluate("a == 5").unwrap(), Value::from(true));
        assert_eq!(evaluate("a != 5").unwrap(), Value::from(false));
        assert_eq!(evaluate("a > d").unwrap(), Value::from(true));
        assert_eq!(evaluate("d < a").unwrap(), Value::from(true));
        assert_eq!(evaluate("d <= 2.5").unwrap(), Value::from(true));
        assert_eq!(evaluate("a >= 6").unwrap(), Value::from(false));
        assert_eq!(evaluate("b < \"y\"").unwrap(), Value::from(true));
        assert_eq!(evaluate("b == \"x\"").unwrap(), Value::from(true));
        assert_eq!(evaluate("c == true").unwrap(), Value::from(true));
        assert_eq!(evaluate("c != false").unwrap(), Value::from(true));
    }

    #[test]
    fn number_comparison_is_numeric() {
        // 整数与浮点数按数值比较 (与 JS 一致)
        assert_eq!(evaluate("5.0 == 5").unwrap(), Value::from(true));
        assert_eq!(evaluate("10 / 2 == 5").unwrap(), Value::from(true));
        assert_eq!(evaluate("1.5 > 1").unwrap(), Value::from(true));
    }

    // -------- 逻辑与条件 --------

    #[test]
    fn logical_and_truthiness() {
        assert_eq!(evaluate("a > 1 && c").unwrap(), Value::from(true));
        assert_eq!(evaluate("a > 10 && c").unwrap(), Value::from(false));
        assert_eq!(evaluate("c || zero").unwrap(), Value::from(true));
        assert_eq!(evaluate("zero || c").unwrap(), Value::from(true));
        assert_eq!(evaluate("zero && c").unwrap(), Value::from(false));
        assert_eq!(evaluate("a && b").unwrap(), Value::from(true));
        assert_eq!(evaluate("zero && b").unwrap(), Value::from(false));
        assert_eq!(evaluate("empty || b").unwrap(), Value::from(true));
        assert_eq!(evaluate("!c").unwrap(), Value::from(false));
        assert_eq!(evaluate("!a").unwrap(), Value::from(false));
        assert_eq!(evaluate("!zero").unwrap(), Value::from(true));
        assert_eq!(evaluate("!empty").unwrap(), Value::from(true));
        assert_eq!(evaluate("!!a").unwrap(), Value::from(true));
    }

    #[test]
    fn short_circuit_skips_unknown_operand() {
        // 左侧已定论时不求值右侧, 未定义的变量不应触发错误
        assert_eq!(evaluate("zero && unknown").unwrap(), Value::from(false));
        assert_eq!(evaluate("a > 10 && unknown").unwrap(), Value::from(false));
        assert_eq!(evaluate("c || unknown").unwrap(), Value::from(true));
        assert_eq!(evaluate("b || unknown").unwrap(), Value::from(true));
        assert_eq!(evaluate("zero ? unknown : 1").unwrap(), Value::from(1));
    }

    #[test]
    fn ternary() {
        assert_eq!(
            evaluate("a > 1 ? \"yes\" : \"no\"").unwrap(),
            Value::from("yes")
        );
        assert_eq!(evaluate("a > 10 ? 1 : 2").unwrap(), Value::from(2));
        assert_eq!(
            evaluate("a > 1 ? (b == \"x\" ? 1 : 2) : 3").unwrap(),
            Value::from(1)
        );
    }

    // -------- 函数调用 --------

    #[test]
    fn function_calls() {
        assert_eq!(evaluate("random(1, 2, 3)").unwrap(), Value::from(7));
        assert_eq!(evaluate("random(1, 2, a + 1)").unwrap(), Value::from(7));
        assert_eq!(evaluate("now()").unwrap(), Value::from(42));
        assert!(matches!(
            evaluate("random(1, 2)").unwrap_err(),
            EvaluationError::ArgumentCount { .. }
        ));
        assert!(matches!(
            evaluate("foo()").unwrap_err(),
            EvaluationError::UnknownFunction(name) if name == "foo"
        ));
    }

    // -------- 变量与裸词 --------

    #[test]
    fn unknown_variable() {
        assert!(matches!(
            evaluate("unknown").unwrap_err(),
            EvaluationError::UnknownVariable(name) if name == "unknown"
        ));
        assert!(matches!(
            evaluate("unknown + 1").unwrap_err(),
            EvaluationError::UnknownVariable(name) if name == "unknown"
        ));
    }

    #[test]
    fn bare_word_falls_back_to_string() {
        assert_eq!(evaluate("人物名称").unwrap(), Value::from("人物名称"));
        assert_eq!(evaluate("你好").unwrap(), Value::from("你好"));
        // 裸词参与条件判断时按真值处理 (与 WebGAL 一致)
        assert_eq!(evaluate("你好 != \"\"").unwrap(), Value::from(true));
    }

    // -------- 深度限制 --------

    #[test]
    fn depth_limit() {
        // 解析器已限制嵌套深度, 这里绕过解析器直接构造深层语法树, 验证求值深度上限
        let mut ast = Expr::Number(Number::Integer(1));
        for _ in 0..200 {
            ast = Expr::Unary(UnOp::Neg, Box::new(ast));
        }
        let expression = Expression { ast };
        assert_eq!(
            expression.evaluate(&Context).unwrap_err(),
            EvaluationError::RecursionLimit
        );
    }
}
